INSERT INTO feature VALUES('method-calls','effects','Method calls','temporary-access','implemented','uncommon','mainstream languages','A module member whose first parameter is `self` is a method, and a call `s.f(a)` on a held receiver is the access its mode lends: `self : shared T` a shared view, `self : T` an exclusive view the body writes through and hands back, `self : consumed T` the hold taken; a receiver that is no held slot is passed as a value, and a method two modules in scope declare is refused naming both. A receiver taken in one arm of a match leaves each other arm the hold the match found, and the hold is spent after the match.','core-term core-checker core-nbe runtime-emitter surface-lowering','corpus/model/strings/methods.gandr corpus/pathological/strings/methods.gandr corpus/pathological/strings/method-ambiguity.gandr corpus/model/control/accessor-method.gandr corpus/pathological/control/accessor-method.gandr','corpus/model/strings/methods.gandr',NULL);
